// WF-16: ADMIN-only console. Body: { admin_email, action, target_email?, department? }
// Actions: TEAM_SUMMARY | OUTSTANDING_REPORTS | LIST_PENDING | APPROVE_REGISTRATION | REJECT_REGISTRATION
const b = $json.body || $json;
const admin = String(b.admin_email || '').toLowerCase().trim();
let action = String(b.action || 'TEAM_SUMMARY').toUpperCase().trim();
const target = String(b.target_email || '').toLowerCase().trim();
const dept = String(b.department || '').trim();
let err = null, sql, params;

if (!admin) { err = 'admin_email is required'; }
else {
  const guard = `WITH a AS (SELECT user_id FROM users WHERE email=$1 AND role='ADMIN')`;
  switch (action) {
    case 'TEAM_SUMMARY':
      sql = `${guard}
SELECT (SELECT count(*) FROM a)::int AS is_admin,
 CASE WHEN EXISTS(SELECT 1 FROM a) THEN (
   SELECT COALESCE(json_agg(row_to_json(t)),'[]') FROM (
     SELECT u.full_name, u.email, u.department,
       (SELECT count(*) FROM attendance x WHERE x.user_id=u.user_id)::int AS days,
       (SELECT count(*) FROM daily_work_entries w WHERE w.user_id=u.user_id)::int AS entries,
       (SELECT count(*) FROM weekly_reports r WHERE r.user_id=u.user_id AND r.status='APPROVED')::int AS approved
     FROM users u WHERE u.role='EMPLOYEE' AND ($2='' OR u.department=$2)
     ORDER BY u.full_name
   ) t
 ) ELSE NULL END AS data`;
      params = [admin, dept];
      break;
    case 'OUTSTANDING_REPORTS':
      sql = `${guard}
SELECT (SELECT count(*) FROM a)::int AS is_admin,
 CASE WHEN EXISTS(SELECT 1 FROM a) THEN (
   SELECT COALESCE(json_agg(row_to_json(t)),'[]') FROM (
     SELECT u.full_name, u.email FROM users u
     WHERE u.role='EMPLOYEE' AND u.status='ACTIVE'
     AND NOT EXISTS (SELECT 1 FROM weekly_reports w WHERE w.user_id=u.user_id
        AND w.iso_year=EXTRACT(ISOYEAR FROM CURRENT_DATE)::int
        AND w.iso_week=EXTRACT(WEEK FROM CURRENT_DATE)::int
        AND w.status IN ('SUBMITTED','UNDER_REVIEW','APPROVED','LOCKED'))
     ORDER BY u.full_name
   ) t
 ) ELSE NULL END AS data`;
      params = [admin, ''];
      break;
    case 'LIST_PENDING':
      sql = `${guard}
SELECT (SELECT count(*) FROM a)::int AS is_admin,
 CASE WHEN EXISTS(SELECT 1 FROM a) THEN (
   SELECT COALESCE(json_agg(row_to_json(t)),'[]') FROM (
     SELECT full_name, email, department, status FROM users
     WHERE status IN ('PENDING','UNDER_REVIEW') ORDER BY created_at
   ) t
 ) ELSE NULL END AS data`;
      params = [admin, ''];
      break;
    case 'APPROVE_REGISTRATION':
    case 'REJECT_REGISTRATION': {
      const newStatus = action === 'APPROVE_REGISTRATION' ? 'ACTIVE' : 'REJECTED';
      const auditAction = action === 'APPROVE_REGISTRATION' ? 'USER_APPROVED' : 'USER_REJECTED';
      const nType = action === 'APPROVE_REGISTRATION' ? 'REGISTRATION_APPROVED' : 'REGISTRATION_REJECTED';
      const nMsg = action === 'APPROVE_REGISTRATION' ? 'Your registration has been approved. Welcome!' : 'Your registration was not approved.';
      sql = `${guard},
upd AS (
  UPDATE users u SET status='${newStatus}'
  FROM a WHERE u.email=$2 AND u.status IN ('PENDING','UNDER_REVIEW')
  RETURNING u.user_id, u.email, u.status
),
aud AS (
  INSERT INTO audit_logs (actor_id, action, record_id, metadata)
  SELECT (SELECT user_id FROM a), '${auditAction}', upd.user_id, json_build_object('email', upd.email)
  FROM upd RETURNING 1
),
notif AS (
  INSERT INTO notifications (user_id, type, message)
  SELECT upd.user_id, '${nType}', '${nMsg}' FROM upd RETURNING 1
)
SELECT (SELECT count(*) FROM a)::int AS is_admin,
       (SELECT COALESCE(json_agg(row_to_json(upd)),'[]') FROM upd) AS data`;
      params = [admin, target];
      break;
    }
    default:
      err = 'Unknown action: ' + action;
  }
}
if (err) { sql = `SELECT 'ERR' AS err`; params = []; }
return [{ json: { err, action, admin, target, sql, params } }];

const built = $('Build Admin').first().json;
const action = built.action;
const d = $json || {};
let reply, data = d.data || null;
const isAdmin = Number(d.is_admin);
if (built.err) { reply = '\u26a0\ufe0f ' + built.err; }
else if (isAdmin === 0) { reply = '\u26d4 Access denied \u2014 ADMIN role required.'; data = null; }
else {
  const arr = Array.isArray(data) ? data : [];
  switch (action) {
    case 'TEAM_SUMMARY':
      reply = `\ud83d\udcca Team summary (${arr.length}):\n` + (arr.map(r => `\u2022 ${r.full_name} \u2014 ${r.days} day(s), ${r.entries} entries, ${r.approved} approved`).join('\n') || '(no employees)');
      break;
    case 'OUTSTANDING_REPORTS':
      reply = arr.length ? `\u23f0 Outstanding weekly reports (${arr.length}):\n` + arr.map(r => `\u2022 ${r.full_name} (${r.email})`).join('\n') : '\u2705 Everyone has submitted this week.';
      break;
    case 'LIST_PENDING':
      reply = arr.length ? `\ud83d\udd53 Pending registrations (${arr.length}):\n` + arr.map(r => `\u2022 ${r.full_name} (${r.email}) \u2014 ${r.department||'?'}`).join('\n') : '\u2705 No pending registrations.';
      break;
    case 'APPROVE_REGISTRATION':
      reply = arr.length ? `\u2705 Approved ${arr[0].email} \u2014 status ${arr[0].status}.` : `\u26a0\ufe0f No pending user matched ${built.target}.`;
      break;
    case 'REJECT_REGISTRATION':
      reply = arr.length ? `\u274c Rejected ${arr[0].email} \u2014 status ${arr[0].status}.` : `\u26a0\ufe0f No pending user matched ${built.target}.`;
      break;
    default:
      reply = 'Done.';
  }
}
return [{ json: { reply, action, data } }];
